Definition init_bytes : gmap Z (bv 8) :=
  list_to_map (List.concat [
    init_bytes_chunk0; init_bytes_chunk1; init_bytes_chunk2
  ]).

(* Total bytes = 2412 (from 892 instructions); keys are byte
   addresses, so [init_bytes !! addr] yields that byte. *)

Global Typeclasses Opaque init_bytes.

(* KEY RANGE.  [init_bytes_lo <= a < init_bytes_hi] for every key [a]: the decidable
   [map_Forall] check, closed by one [vm_compute], so the proof term is
   [eq_refl] and no list ever enters it.  Bounds are LITERALS (this file
   is below iris/ and cannot name [ram_lo]/[text_end]/[img_end]); the
   consumer bridges them arithmetically. *)
Definition init_bytes_lo : Z := 0x0%Z.
Definition init_bytes_hi : Z := 0x96c%Z.

Lemma init_bytes_range_bool :
  bool_decide (map_Forall (fun (a : Z) (_ : bv 8) =>
                 (init_bytes_lo <= a < init_bytes_hi)%Z) init_bytes) = true.
Proof. vm_compute. reflexivity. Qed.

Lemma init_bytes_range (a : Z) (b : bv 8) :
  init_bytes !! a = Some b -> (init_bytes_lo <= a < init_bytes_hi)%Z.
Proof.
  pose proof init_bytes_range_bool as H.
  apply bool_decide_eq_true_1 in H. exact (H a b).
Qed.

